-- Run as the existing operator in commerce_language. No customer rows returned.
BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL statement_timeout = '15s';
SET LOCAL lock_timeout = '2s';
SELECT json_build_object('kind','identity','capturedAt',now(),'serverVersion',current_setting('server_version'),'database',current_database());
SELECT json_build_object('kind','activeRelease','rows',json_agg(x)) FROM (SELECT c.channel,c.updated_at,d.id,d.fingerprint,d.dictionary_version,d.schema_version,d.artifact->'languageKnowledge'->>'revision' AS knowledge_revision FROM release.channels c JOIN release.dictionaries d ON d.id=c.release_id) x;
SELECT json_build_object('kind','migration','rows',json_agg(m)) FROM public.schema_migrations m;
SELECT json_build_object('kind','databaseSizes','rows',json_agg(x)) FROM (SELECT datname,pg_database_size(oid) AS bytes FROM pg_database WHERE datname IN ('assistant','commerce_language')) x;
SELECT json_build_object('kind','relations','rows',json_agg(x)) FROM (SELECT n.nspname AS schema,c.relname AS name,c.relkind,c.reltuples::bigint AS estimated_rows,pg_total_relation_size(c.oid) AS total_bytes,pg_indexes_size(c.oid) AS index_bytes FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname NOT IN ('pg_catalog','information_schema') AND n.nspname NOT LIKE 'pg_toast%' AND c.relkind IN ('r','m') ORDER BY total_bytes DESC) x;
SELECT json_build_object('kind','columns','rows',json_agg(x)) FROM (SELECT table_schema,table_name,column_name,data_type,is_nullable,column_default FROM information_schema.columns WHERE table_schema NOT IN ('pg_catalog','information_schema') ORDER BY table_schema,table_name,ordinal_position) x;
SELECT json_build_object('kind','indexes','rows',json_agg(x)) FROM (SELECT schemaname,tablename,indexname,indexdef FROM pg_indexes WHERE schemaname NOT IN ('pg_catalog','information_schema') ORDER BY 1,2,3) x;
SELECT json_build_object('kind','constraints','rows',json_agg(x)) FROM (SELECT n.nspname AS schema,c.relname AS table_name,k.conname AS name,k.contype AS type,pg_get_constraintdef(k.oid) AS definition FROM pg_constraint k JOIN pg_class c ON c.oid=k.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname NOT IN ('pg_catalog','information_schema') ORDER BY 1,2,3) x;
SELECT json_build_object('kind','reviewedDatasets','rows',COALESCE(json_agg(x),'[]'::json)) FROM (SELECT id,code,revision,sha256,reviewed_by,created_at FROM evaluation.datasets ORDER BY created_at) x;
SELECT json_build_object('kind','counts','rows',json_build_object('lexiconTerms',(SELECT count(*) FROM lexicon.terms),'entityTerms',(SELECT count(*) FROM entity.terms),'entityAliases',(SELECT count(*) FROM entity.aliases),'intents',(SELECT count(*) FROM intent.definitions),'intentRules',(SELECT count(*) FROM intent.rules),'semanticGroups',(SELECT count(*) FROM semantic.groups),'semanticTerms',(SELECT count(*) FROM semantic.terms),'knowledgePacks',(SELECT count(*) FROM knowledge.packs),'reviewedCases',(SELECT count(*) FROM evaluation.cases),'feedbackReviews',(SELECT count(*) FROM resolution.feedback_reviews)));
SELECT json_build_object('kind','knowledgePacks','rows',json_agg(x)) FROM (SELECT p.code,p.revision,p.sha256,(SELECT count(*) FROM knowledge.concepts c WHERE c.pack_sha256=p.sha256) AS concepts,(SELECT count(*) FROM knowledge.aliases a WHERE a.pack_sha256=p.sha256) AS forms,(SELECT count(*) FROM knowledge.rules r WHERE r.pack_sha256=p.sha256) AS relationships,(SELECT count(*) FROM knowledge.utterance_rules u WHERE u.pack_sha256=p.sha256) AS utterance_rules,(SELECT count(*) FROM knowledge.question_rules q WHERE q.pack_sha256=p.sha256) AS question_rules FROM knowledge.packs p ORDER BY p.code,p.revision) x;
SELECT json_build_object('kind','queryPlan','name','active_release');
EXPLAIN (ANALYZE, BUFFERS, FORMAT JSON) SELECT d.id,d.fingerprint FROM release.channels c JOIN release.dictionaries d ON d.id=c.release_id WHERE c.channel='production';
SELECT json_build_object('kind','queryPlan','name','concept_lookup');
EXPLAIN (ANALYZE, BUFFERS, FORMAT JSON) SELECT code,canonical,metadata FROM knowledge.concepts WHERE code='activity.video_editing' AND pack_sha256=(SELECT p.sha256 FROM knowledge.packs p JOIN release.channels c ON c.channel='production' JOIN release.dictionaries d ON d.id=c.release_id WHERE p.code=d.artifact->'languageKnowledge'->>'id' AND p.revision=(d.artifact->'languageKnowledge'->>'revision')::integer);
SELECT json_build_object('kind','queryPlan','name','lexicon_exact_lookup');
EXPLAIN (ANALYZE, BUFFERS, FORMAT JSON) SELECT id,term FROM lexicon.terms WHERE normalized_term='laptop' AND active;
COMMIT;
